///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/list/prelist.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name vailidationLn
 * @description vailidation Ln 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.vailidationLn = async function () {
    if (!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) {
        return false;
    }
    if (!await (async () => { const vars = scwin.maxLenCheckVars || []; const names =  scwin.maxLenCheckNames || []; const maxes =  scwin.maxLenCheckMax || []; for (let i = 0; i < vars.length; i++) { const c = $c.util.getComponent(vars[i]); if (!c || !c.getValue) { continue; } const len = $c.str.getByteLength(String(c.getValue() ?? "")); const max = Number(maxes[i]) || 0; if (max && len > max) { await $c.win.alert(String(names[i]) + "의 최대길이(" + max + ")를 \n" + (len - max) + " Byte 만큼 초과하였습니다.\n수정후 저장하세요"); if (c.setFocus) { c.setFocus(); } return false; } } return true; })()) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name setDataRadio
 * @description set Data Radio 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setDataRadio = async function () {
    if (!await scwin.setRadioValue("ventfncStkHdYn1", "ventfncStkHdYn", "벤처금융주식보유여부")) {
        $c.util.getComponent('rd_ventfncStkHdYn1').focus();
        return false;
    }
    if (!await scwin.setRadioValue("listBrokerStkHdYn1", "listBrokerStkHdYn", "상장주선인주식보유여부")) {
        $c.util.getComponent('rd_listBrokerStkHdYn1').focus();
        return false;
    }
    if (!await scwin.setRadioValue("ventfncEmpStkHdYn1", "ventfncEmpStkHdYn", "벤처금융임직원주식보유여부")) {
        $c.util.getComponent('rd_ventfncEmpStkHdYn1').focus();
        return false;
    }
    if (!await scwin.setRadioValue("listBrokerEmpStkHdYn1", "listBrokerEmpStkHdYn", "상장주선인임직원주식보유여부")) {
        $c.util.getComponent('rd_listBrokerEmpStkHdYn1').focus();
        return false;
    }
    if (!await scwin.setRadioValue("empstkassoYn1", "empstkassoYn", "우리사주조합여부")) {
        $c.util.getComponent('rd_empstkassoYn1').focus();
        return false;
    }
    if (!await scwin.setRadioValue("stkoptYn1", "stkoptYn", "스톡옵션여부")) {
        $c.util.getComponent('rd_stkoptYn1').focus();
        return false;
    }
    if (!await scwin.setRadioValue("cbIsuYn1", "cbIsuYn", "전환사채발행여부")) {
        $c.util.getComponent('rd_cbIsuYn1').focus();
        return false;
    }
    if (!await scwin.setRadioValue("cbNconvYn1", "cbNconvYn", "전환사채미전환여부")) {
        $c.util.getComponent('rd_cbNconvYn1').focus();
        return false;
    }
    if (!await scwin.setRadioValue("bwIsuYn1", "bwIsuYn", "BW발행여부")) {
        $c.util.getComponent('rd_bwIsuYn1').focus();
        return false;
    }
    if (!await scwin.setRadioValue("bwNconvYn1", "bwNconvYn", "BW미전환여부")) {
        $c.util.getComponent('rd_bwNconvYn1').focus();
        return false;
    }
    if (!await scwin.setRadioValue("smallPubofrYn1", "smallPubofrYn", "소액공모여부")) {
        $c.util.getComponent('rd_smallPubofrYn1').focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (await scwin.vailidationLn() === false) {
        return;
    }
    if (!await scwin.setDataRadio()) {
        return;
    }
    scwin.rmCommaValueAll();
    scwin.form.action = '/list/prelist.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistReg');
    await scwin.tx_fn_Register();
};

