/**
 * @method
 * @name setRadioValue
 * @description set Radio Value 처리
 * @param {*} radioName radioName
 * @param {*} formParamName formParamName
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setRadioValue = async function (radioName, formParamName, msg) {
    const i = 0;
    {
        const rv = String($c.util.getComponent('dma_RegisterReq').get(radioName) ?? '');
        if (rv === '') {
            await $c.win.alert(msg + " 항목을 선택해주세요.");
            return false;
        }
        $c.util.getComponent('dma_RegisterReq').set(formParamName, rv);
    }
    return true;
};

