    $c.fil.setComma($c.util.getComponent('ipt_ovr1PctRelprnPrefstkShrs')); //  1PCT이상관계자우선주주식수
    $c.fil.setComma($c.util.getComponent('ipt_minshrhdCnt')); //  소액주주수
    $c.fil.setComma($c.util.getComponent('ipt_minshrhdCmstkShrs')); //  소액주주보통주주식수
    $c.fil.setComma($c.util.getComponent('ipt_minshrhdPrefstkShrs')); //  소액주주우선주주식수
    $c.fil.setComma($c.util.getComponent('ipt_ventcapCnt')); //  벤처캐피탈수
    $c.fil.setComma($c.util.getComponent('ipt_ventcapCmstkShrs')); //  벤처캐피탈보통주주식수
    $c.fil.setComma($c.util.getComponent('ipt_ventcapPrefstkShrs')); //  벤처캐피탈우선주주식수
    $c.fil.setComma($c.util.getComponent('ipt_instInvstCnt')); //  기관투자자수
    $c.fil.setComma($c.util.getComponent('ipt_instInvstCmstkShrs')); //  기관투자자보통주주식수
    $c.fil.setComma($c.util.getComponent('ipt_instInvstPrefstkShrs')); //  기관투자자우선주주식수
    $c.fil.setComma($c.util.getComponent('ipt_empstkassoGrntprnCnt')); //  우리사주조합부여자수
    $c.fil.setComma($c.util.getComponent('ipt_empstkassoGrntShrs')); //  우리사주조합부여주식수
    $c.fil.setComma($c.util.getComponent('ipt_stkoptGrntprnCnt')); //  스톡옵션부여자수
    $c.fil.setComma($c.util.getComponent('ipt_stkoptGrntShrs')); //  스톡옵션부여주식수
};

/**
 * @method
 * @name majChange
 * @description maj Change 처리
 * @returns {void}
 * @hidden N
 */
scwin.majChange = function () {
    // 최대주주 합계주식수
    $c.util.getComponent('ipt_sumLgShr').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_lgshrhdCmstkShrs').getValue()) + scwin.rmComma($c.util.getComponent('ipt_lgshrhdPrefstkShrs').getValue())));

    // 최대주주 관계자 합계주식수
    $c.util.getComponent('ipt_sumRelShr').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_lgshrhdRelprnCmstkShrs').getValue()) + scwin.rmComma($c.util.getComponent('ipt_lgshrhdRelprnPrefstkShrs').getValue())));

    // 최대주주 보통주 소계  주식수
    $c.util.getComponent('ipt_sumSubCmn').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_lgshrhdCmstkShrs').getValue()) + scwin.rmComma($c.util.getComponent('ipt_lgshrhdRelprnCmstkShrs').getValue())));

    // 최대주주 우선주 소계 주식수
    $c.util.getComponent('ipt_sumSubPref').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_lgshrhdPrefstkShrs').getValue()) + scwin.rmComma($c.util.getComponent('ipt_lgshrhdRelprnPrefstkShrs').getValue())));

    // 최대주주 보통+우선주 소계 주식수
    $c.util.getComponent('ipt_sumSubTot').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_sumLgShr').getValue()) + scwin.rmComma($c.util.getComponent('ipt_sumRelShr').getValue())));

    fn_TotalChange();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_TotalChange — as-is 공통(폼 전역 의존) — 반입 보류

};

/**
 * @method
 * @name prelistPageSearch
 * @description prelist Page Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prelistPageSearch = async function () {
    scwin.form.action       = '/list/prelistPage.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistPageSearch');
    await moveUrl('/list/prelistPage.do', {});

};

/**
 * @method
 * @name allManChange
 * @description all Man Change 처리
 * @returns {void}
 * @hidden N
 */
scwin.allManChange = function () {
    $c.util.getComponent('ipt_sumTotCnt').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_lgshrhdRelprnCnt').getValue()) +
            scwin.rmComma($c.util.getComponent('ipt_ovr5PctRelprnCnt').getValue()) +
            scwin.rmComma($c.util.getComponent('ipt_ovr1PctRelprnCnt').getValue()) +
            scwin.rmComma($c.util.getComponent('ipt_minshrhdCnt').getValue()) + fn_SumAllStockHolder()));  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_SumAllStockHolder — as-is 공통(폼 전역 의존) — 반입 보류

};

/**
 * @method
 * @name rmComma
 * @description ── as-is 화면 전용 함수 인라인 ──
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.rmComma = function (str){
    //    if( str == null || str == "" || str == 0 ) return '';
    //    if( str == null || str == ""  ) return '';
    if( str == null || str === ""  ) return Number(str);   // 2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");

    return Number(str.replace(reg,''));
};
